head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[p > M > watermark]<br/>화면에 Canvas 기반의 워터마크를 표시합니다.",
    "validation" : [
        "화면에 Canvas 기반의 워터마크를 표시해야 합니다.",
        "워터마크에는 label 파라미터에 설정한 문자열과 'yyyy-MM-dd HH:mm:ss' 형식의 현재 날짜 및 시간이 포함되어야 합니다.",
        "label(필수) 파라미터로 워터마크로 표시할 문자열을 설정할 수 있어야 합니다.",
        "options(선택) 파라미터로 워터마크 옵션을 JSON 객체로 설정할 수 있어야 합니다.",
        "options.canvasId(선택) 파라미터로 Canvas 요소의 ID 를 설정할 수 있어야 합니다.",
        "options.target(선택) 파라미터로 워터마크를 표시할 대상 컴포넌트를 설정할 수 있어야 합니다 (생략 시 document.body).",
        "options.lineGap(선택) 파라미터로 워터마크 줄 간격(px)을 설정할 수 있어야 합니다."
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 기존 워터마크 canvas 제거 (케이스 간 독립성 확보)
scwin.removeWatermarkCanvas = function () {
    var canvases = document.querySelectorAll("canvas[data-watermark_msg]");
    for (var i = 0; i < canvases.length; i++) {
        if (canvases[i].parentNode) {
            canvases[i].parentNode.removeChild(canvases[i]);
        }
    }
};



// Canvas 상태 출력 (존재 / parent / 속성 / 렌더링 픽셀)
scwin.printCanvasStatus = function (canvasId) {
    var canvas = document.getElementById(canvasId);
    if (!canvas) {
        wf_body_bottom.getObj("scwin").setReturnValue("canvas[id='" + canvasId + "'] : 없음");
        return;
    }
    wf_body_bottom.getObj("scwin").setReturnValue("canvas 생성됨 : id='" + canvas.id + "', size=" + canvas.width + "x" + canvas.height);
    wf_body_bottom.getObj("scwin").setReturnValue("canvas parent : <" + canvas.parentNode.tagName + (canvas.parentNode.id ? " id='" + canvas.parentNode.id + "'" : "") + ">");
    wf_body_bottom.getObj("scwin").setReturnValue("data-watermark_msg : " + canvas.getAttribute("data-watermark_msg"));
    wf_body_bottom.getObj("scwin").setReturnValue("data-watermark_linegap : " + canvas.getAttribute("data-watermark_linegap"));

    // 렌더링 확인 : 반투명 픽셀 존재 여부
    try {
        var ctx = canvas.getContext("2d");
        var imgData = ctx.getImageData(0, 0, canvas.width, canvas.height);
        var data = imgData.data;
        var count = 0;
        for (var i = 3; i < data.length; i += 16) {
            if (data[i] > 0 && data[i] < 255) count++;
        }
        wf_body_bottom.getObj("scwin").setReturnValue("반투명 픽셀(샘플) : " + count + " → " + (count > 0 ? "렌더링 확인됨" : "비어있음"));
    } catch (e) {
        wf_body_bottom.getObj("scwin").setReturnValue("getImageData 예외 : " + e.message);
    }
};



scwin.btn_watermark_onclick = function () {
    var scenario = par_scenario.getValue();
    var label = par_label.getValue();
    var canvasId = par_canvasId.getValue();
    var lineGap = parseInt(par_lineGap.getValue(), 10);

    scwin.removeWatermarkCanvas();

    if (scenario === "1") {
        // target 생략 → document.body 에 표시 (label + canvasId + lineGap 전체 설정)
        var options = { canvasId : canvasId, lineGap : lineGap };
        $p.watermark(label, options);
        wf_body_bottom.getObj("scwin").setReturnValue("$p.watermark('" + label + "', { canvasId:'" + canvasId + "', lineGap:" + lineGap + " }) 실행 (target 생략)");
    } else if (scenario === "2") {
        // target 지정 → grp_target 영역에 표시 (모든 options 설정)
        var options = { canvasId : canvasId, target : grp_target, lineGap : lineGap };
        $p.watermark(label, options);
        wf_body_bottom.getObj("scwin").setReturnValue("$p.watermark('" + label + "', { canvasId:'" + canvasId + "', target:grp_target, lineGap:" + lineGap + " }) 실행");
    }

    setTimeout(function () {
        scwin.printCanvasStatus(canvasId);
    }, 300);
};



scwin.btn_removeCanvas_onclick = function () {
    scwin.removeWatermarkCanvas();
    wf_body_bottom.getObj("scwin").setReturnValue("워터마크 canvas 제거 실행");
};
